/**
 * postman-playwright — Public API
 *
 * Recommended path (config-only, no spec changes):
 *
 *     import { defineConfig } from '@playwright/test'
 *     import { withPostman } from 'postman-playwright'
 *     export default withPostman(defineConfig({ ... }))
 *
 * `withPostman` injects Playwright's built-in `json` reporter (writing to
 * `test-results/playwright-report.json`) and forces `use.trace` to a tuned
 * mode. The Postman CLI consumes the JSON report plus the per-test
 * `trace.zip` files Playwright already produces under `test-results/`.
 *
 * `attachNetworkCapture` is kept for backward compatibility (legacy NDJSON
 * capture stream).
 */
export { attachNetworkCapture } from './networkLogger';
export { withPostman } from './withPostman';
